inline constexpr std::uint32_t FRESH_ROWS = 3330;

/// The table's first row, byte for byte. Resent unchanged after one of our own rows
/// is added: the client rebuilds the table's spell index only when a pushed row updates
/// a row it already holds, and without that rebuild an added row is never seen. The
/// values are identical to what the client already has, so the update changes nothing.
inline constexpr Row RefreshRow = { 1, 1, 0, 536870912, 0, 0, 0, 0, 0, 0, 0 };

